1	type Item = { type: string; cursed?: boolean; enchantment?: number };
2	
3	const basePremiumsByType: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40, rune: 25, moonstone: 25 };
4	
5	const BLOCK_SIZE = 3;
6	const BLOCK_PREMIUM = 60;
7	
8	const sumOverItems = (items: Item[], perItem: (item: Item) => number): number =>
9	  items.reduce((sum, item) => sum + perItem(item), 0);
10	
11	const basePremiumForItem = (item: Item): number => basePremiumsByType[item.type];
12	
13	const sumOfItemBasePremiums = (items: Item[]): number =>
14	  sumOverItems(items, basePremiumForItem);
15	
16	const groupByType = (items: Item[]): Item[][] => {
17	  const groups = new Map<string, Item[]>();
18	  for (const item of items) {
19	    const group = groups.get(item.type) ?? [];
20	    group.push(item);
21	    groups.set(item.type, group);
22	  }
23	  return [...groups.values()];
24	};
25	
26	const basePremiumForGroup = (group: Item[]): number =>
27	  group.length === BLOCK_SIZE ? BLOCK_PREMIUM : sumOfItemBasePremiums(group);
28	
29	export const basePremium = (items: Item[]): number =>
30	  groupByType(items).reduce((sum, group) => sum + basePremiumForGroup(group), 0);
31	
32	const PROCESSING_FEE = 5;
33	
34	type Customer = { yearsWithMHPCO: number };
35	type QuoteStep = { op: "quote"; items: Item[] };
36	type Scenario = { customer: Customer; steps: QuoteStep[] };
37	
38	const CURSE_SURCHARGE_RATE = 0.5;
39	const HIGH_ENCHANTMENT_RATE = 0.3;
40	const HIGH_ENCHANTMENT_THRESHOLD = 5;
41	const FIRST_INSURANCE_RATE = 0.1;
42	const LOYALTY_RATE = 0.2;
43	const LOYALTY_THRESHOLD = 2;
44	
45	const surchargeOf = (item: Item, rate: number): number => basePremiumForItem(item) * rate;
46	
47	const curseSurchargeForItem = (item: Item): number =>
48	  item.cursed ? surchargeOf(item, CURSE_SURCHARGE_RATE) : 0;
49	
50	const curseSurcharge = (items: Item[]): number =>
51	  sumOverItems(items, curseSurchargeForItem);
52	
53	const highEnchantmentSurchargeForItem = (item: Item): number =>
54	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
55	    ? surchargeOf(item, HIGH_ENCHANTMENT_RATE)
56	    : 0;
57	
58	const highEnchantmentSurcharge = (items: Item[]): number =>
59	  sumOverItems(items, highEnchantmentSurchargeForItem);
60	
61	const firstInsuranceSurcharge = (policyBase: number): number => policyBase * FIRST_INSURANCE_RATE;
62	
63	const loyaltyDiscount = (policyBase: number, customer: Customer): number =>
64	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD ? policyBase * LOYALTY_RATE : 0;
65	
66	const quotePremium = (step: QuoteStep, customer: Customer): number => {
67	  const items = step.items;
68	  const policyBase = basePremium(items);
69	  const surcharges =
70	    curseSurcharge(items) +
71	    highEnchantmentSurcharge(items) +
72	    firstInsuranceSurcharge(policyBase);
73	  return policyBase + surcharges - loyaltyDiscount(policyBase, customer) + PROCESSING_FEE;
74	};
75	
76	export const runScenario = (scenario: Scenario): { results: { premium: number }[] } => ({
77	  results: scenario.steps.map((step) => ({ premium: quotePremium(step, scenario.customer) })),
78	});
