const itemSurcharges = (items: Item[]): number =>
  curseSurcharge(items) + highEnchantmentSurcharge(items);

const quotePremium = (step: QuoteStep, customer: Customer): number => {
  const items = step.items;
  const policyBase = basePremium(items);
  const surcharges = itemSurcharges(items) + firstInsuranceSurcharge(policyBase);
  return policyBase + surcharges - loyaltyDiscount(policyBase, customer) + PROCESSING_FEE;
};
